local AngelusBellMaker = {}
local PRODUCTS = {
    plain_iron_angelus = { name = "Preprost železni angelus zvonec", ironCost = 2, woodCost = 2, ropeCost = 1, time = 5, cost = 170, happiness = 1, prestige = 3, description = "Preprost angelus zvonec za kapelo." },
    bronze_chapel_angelus = { name = "Bronast kapelni angelus", bronzeCost = 2, ironCost = 1, woodCost = 2, ropeCost = 1, time = 8, cost = 430, happiness = 2, prestige = 7, description = "Bronast angelus za kapelo zbrane molitve." },
    silver_convent_angelus = { name = "Srebrni samostanski angelus", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, ropeCost = 1, time = 12, cost = 1120, happiness = 3, prestige = 14, description = "Srebrni angelus za samostan." },
    gilded_cathedral_angelus = { name = "Pozlačeni katedralski angelus", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, ropeCost = 1, time = 16, cost = 2600, happiness = 4, prestige = 26, description = "Pozlačeni angelus za katedralo." },
    jewel_set_royal_angelus = { name = "Draguljasta kraljevska angelus", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, ropeCost = 1, time = 20, cost = 5400, happiness = 6, prestige = 46, description = "Draguljast angelus za kraljevo kapelo." },
    sovereign_sanctus_angelus = { name = "Suvereni sanctus angelus", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, ropeCost = 1, time = 27, cost = 11800, happiness = 12, prestige = 84, description = "Suvereni sanctus zvonec z biseri za krono." },
}
local BUILDINGS = {
    angelus_workshop = { name = "Angelus delavnica", cost = { gold = 340, wood = 160, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    sacring_bell_house = { name = "Posvetilna zvončna hiša", cost = { gold = 1200, wood = 320, stone = 240, silver = 6, iron = 6 }, upkeep = 26, qualityBonus = 18 },
    master_angelus_atelier = { name = "Mojstrski angelus atelje", cost = { gold = 3050, wood = 400, stone = 500, silver = 36, gold = 6 }, upkeep = 73, qualityBonus = 30 },
    sovereign_sanctus_palace = { name = "Suverena sanctus palača", cost = { gold = 13800, wood = 650, stone = 850, gold = 85, jewel = 18 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
AngelusBellMaker.ironStock = 12; AngelusBellMaker.bronzeStock = 10; AngelusBellMaker.woodStock = 14; AngelusBellMaker.ropeStock = 10; AngelusBellMaker.silverStock = 8; AngelusBellMaker.goldStock = 6; AngelusBellMaker.jewelStock = 4; AngelusBellMaker.pearlStock = 4
AngelusBellMaker.productStock = {}; AngelusBellMaker.buildings = {}; AngelusBellMaker.maker = nil; AngelusBellMaker.activeMaking = {}; AngelusBellMaker.totalProducts = 0; AngelusBellMaker.dayTimer = 0
function AngelusBellMaker.init() AngelusBellMaker.ironStock=12; AngelusBellMaker.bronzeStock=10; AngelusBellMaker.woodStock=14; AngelusBellMaker.ropeStock=10; AngelusBellMaker.silverStock=8; AngelusBellMaker.goldStock=6; AngelusBellMaker.jewelStock=4; AngelusBellMaker.pearlStock=4; AngelusBellMaker.productStock={}; AngelusBellMaker.buildings={}; AngelusBellMaker.maker=nil; AngelusBellMaker.activeMaking={}; AngelusBellMaker.totalProducts=0; AngelusBellMaker.dayTimer=0; print("[AngelusBellMaker] Royal Angelus Bell Maker System initialized (6 products, 4 buildings)") end
function AngelusBellMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AngelusBellMaker.maker={name=n or ("Angelusar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Angelusar najet: %s (spretnost: %d)",AngelusBellMaker.maker.name,s),"success") end; return true end
function AngelusBellMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AngelusBellMaker.build(id) local ok,e=AngelusBellMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AngelusBellMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AngelusBellMaker.getQualityBonus() local b=0; for _,bd in ipairs(AngelusBellMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AngelusBellMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AngelusBellMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AngelusBellMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AngelusBellMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ropeCost and AngelusBellMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and AngelusBellMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AngelusBellMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AngelusBellMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AngelusBellMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AngelusBellMaker.buildings==0 then return false,"Potrebna angelus delavnica" end; if not AngelusBellMaker.maker then return false,"Potreben angelusar" end; return true end
function AngelusBellMaker.make(pt,qty) qty=qty or 1; local ok,e=AngelusBellMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AngelusBellMaker.ironStock=AngelusBellMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AngelusBellMaker.bronzeStock=AngelusBellMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AngelusBellMaker.woodStock=AngelusBellMaker.woodStock-d.woodCost*qty end; if d.ropeCost then AngelusBellMaker.ropeStock=AngelusBellMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then AngelusBellMaker.silverStock=AngelusBellMaker.silverStock-d.silverCost*qty end; if d.goldCost then AngelusBellMaker.goldStock=AngelusBellMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AngelusBellMaker.jewelStock=AngelusBellMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AngelusBellMaker.pearlStock=AngelusBellMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AngelusBellMaker.maker then t=math.max(1,t-math.floor(AngelusBellMaker.maker.skill/13)) end; table.insert(AngelusBellMaker.activeMaking,{id="angelus_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AngelusBellMaker.completeMaking(m) local q=1.0+(AngelusBellMaker.getQualityBonus()/100); if AngelusBellMaker.maker then q=q+(AngelusBellMaker.maker.skill/140) end; q=math.min(2.5,q); AngelusBellMaker.productStock[m.productType]=(AngelusBellMaker.productStock[m.productType] or 0)+m.quantity; AngelusBellMaker.totalProducts=AngelusBellMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AngelusBellMaker.maker then AngelusBellMaker.maker.itemsMade=AngelusBellMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AngelusBellMaker.maker.skill=math.min(100,AngelusBellMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Angelus izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"angelus.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AngelusBellMaker.update(dt) if not _G.state then return end; AngelusBellMaker.dayTimer=AngelusBellMaker.dayTimer+dt; if AngelusBellMaker.dayTimer>=30 then AngelusBellMaker.dayTimer=0; for i=#AngelusBellMaker.activeMaking,1,-1 do local m=AngelusBellMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AngelusBellMaker.completeMaking(m); table.remove(AngelusBellMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AngelusBellMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AngelusBellMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AngelusBellMaker.getStats() return {ironStock=AngelusBellMaker.ironStock,bronzeStock=AngelusBellMaker.bronzeStock,woodStock=AngelusBellMaker.woodStock,ropeStock=AngelusBellMaker.ropeStock,silverStock=AngelusBellMaker.silverStock,goldStock=AngelusBellMaker.goldStock,jewelStock=AngelusBellMaker.jewelStock,pearlStock=AngelusBellMaker.pearlStock,productStock=AngelusBellMaker.productStock,numBuildings=#AngelusBellMaker.buildings,hasMaker=AngelusBellMaker.maker~=nil,makerName=AngelusBellMaker.maker and AngelusBellMaker.maker.name or "—",makerSkill=AngelusBellMaker.maker and AngelusBellMaker.maker.skill or 0,activeMaking=#AngelusBellMaker.activeMaking,totalProducts=AngelusBellMaker.totalProducts} end
return AngelusBellMaker
